def launcher_managed_runtime_specs(runtime: str) -> tuple[tuple[str, str, str], ...]:
    """Discover isolated, versioned runtimes installed for this launcher."""
    if runtime != "omlx":
        return ()
    try:
        paths = sorted(
            MANAGED_RUNTIMES_DIR.glob("omlx-*/bin/omlx"),
            key=lambda item: item.parent.parent.name.lower(),
        )
    except OSError:
        return ()
    result: list[tuple[str, str, str]] = []
    for path in paths:
        version = path.parent.parent.name.removeprefix("omlx-")
        label = f"Launcher-managed {version}" if version else "Launcher-managed oMLX"
        result.append(("launcher-managed", str(path), label))
    return tuple(result)


def runtime_candidates(runtime: str) -> list[dict[str, str]]:
    """Return known installed runtime entry points, deduplicated by target."""
    candidates: list[dict[str, str]] = []
    seen: set[str] = set()
    specs = (
        *RUNTIME_CANDIDATE_SPECS.get(runtime, ()),
        *launcher_managed_runtime_specs(runtime),
    )
    for channel, requested, label in specs:
        path = executable([requested])
        if not path:
            continue
        try:
            resolved = str(Path(path).expanduser().resolve(strict=True))
        except OSError:
            continue
        if resolved in seen:
            continue
        seen.add(resolved)
        candidate_id = hashlib.sha256(
            f"{runtime}\0{resolved}".encode("utf-8", "replace")
        ).hexdigest()[:16]
        candidates.append({
            "id": candidate_id,
            "runtime": runtime,
            "path": str(Path(path).expanduser()),
            "resolvedPath": resolved,
            "channel": channel,
            "channelLabel": label,
        })
    return candidates


def runtime_executable_revision(path_value: Any) -> dict[str, Any]:
    """Bind promotion evidence to the exact executable bytes and filesystem revision."""
    try:
        path = Path(str(path_value or "")).expanduser().resolve(strict=True)
        details = path.stat()
    except OSError as error:
        raise ValueError("The installed runtime executable could not be revalidated.") from error
    if not path.is_file() or not os.access(path, os.X_OK):
        raise ValueError("The installed runtime candidate is no longer executable.")
    if details.st_size <= 0 or details.st_size > 512 * 1024**2:
        raise ValueError("The installed runtime executable has an unexpected size.")
    digest = hashlib.sha256()
    try:
        with open(path, "rb") as handle:
            while chunk := handle.read(1024 * 1024):
                digest.update(chunk)
    except OSError as error:
        raise ValueError("The installed runtime executable changed while it was being identified.") from error
    identity = {
        "resolvedPath": str(path),
        "size": details.st_size,
        "modifiedNs": details.st_mtime_ns,
        "sha256": digest.hexdigest(),
    }
    identity["id"] = hashlib.sha256(json.dumps(
        identity, sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()[:24]
    return identity


def preferred_runtime_binary(runtime: str) -> str | None:
    candidates = runtime_candidates(runtime)
    preferences = read_json(RUNTIME_PREFERENCES_FILE)
    selections = preferences.get("selections")
    preferred = selections.get(runtime) if isinstance(selections, dict) else None
    if isinstance(preferred, str):
        for candidate in candidates:
            if candidate["id"] == preferred:
                return candidate["path"]
    return candidates[0]["path"] if candidates else None


